CREATE INDEX "productos_boleta_usuario_id_93974c51" ON "productos_boleta" ("usuario_id");
CREATE INDEX "productos_detalleboleta_boleta_id_561ca8a7" ON "productos_detalleboleta" ("boleta_id");
CREATE INDEX "productos_detalleboleta_producto_id_c499c9b0" ON "productos_detalleboleta" ("producto_id");
CREATE INDEX "productos_gasto_usuario_id_9e8d19f9" ON "productos_gasto" ("usuario_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
COMMIT;
